/**
 * Test doubles for the `src/lib` helpers owned by E.
 *
 * The server layer legitimately depends on them, but they are still stubs at
 * the time this suite runs, so each is replaced with the smallest faithful
 * implementation the assertions need. Swap-in only — no server code is mocked.
 */
import type { UserId } from "@/types/common";
import type { MemberWithUser } from "@/types/member";
import type { IsoTimestamp, OrgId } from "@/types/common";

/* -------------------------------------------------------------- @/lib/hash */

export const hashModule = {
  hashPassword: async (password: string): Promise<string> =>
    `scrypt$${password.length}$${simpleHash(password)}`,
  verifyPassword: async (password: string, hash: string): Promise<boolean> =>
    (await hashModule.hashPassword(password)) === hash,
  hashToken: (token: string): string => `sha256$${simpleHash(token)}`,
  randomToken: (bytes = 32): string =>
    `t${simpleHash(String(tokenCounter++))}`.padEnd(bytes, "x"),
};

let tokenCounter = 1;

/* -------------------------------------------------------- @/lib/rate-limit */

/** Verdicts the suite can steer: the default is "always allowed". */
export const rateLimitState = { allowed: true, remaining: 100 };

export const rateLimitModule = {
  consumeRateLimit: async (
    _orgId: OrgId,
    _bucketKey: string,
    cost = 1,
  ): Promise<{
    allowed: boolean;
    remaining: number;
    resetAt: IsoTimestamp;
  }> => ({
    allowed: rateLimitState.allowed,
    remaining: Math.max(0, rateLimitState.remaining - cost),
    resetAt: new Date(Date.now() + 60_000).toISOString() as IsoTimestamp,
  }),
  getBucketConfig: () => ({ capacity: 100, refillPerMinute: 100 }),
  RATE_LIMIT_BUCKETS: {} as Readonly<
    Record<string, { capacity: number; refillPerMinute: number }>
  >,
};

/* ---------------------------------------------------------- @/lib/mentions */

export const mentionsModule = {
  extractMentions: (body: string): readonly string[] =>
    [...body.matchAll(/@([\w.-]+)/g)].map((match) => match[1] ?? ""),
  resolveMentions: (
    body: string,
    members: readonly MemberWithUser[],
  ): readonly UserId[] => {
    const handles = new Set(
      mentionsModule.extractMentions(body).map((handle) => handle.toLowerCase()),
    );
    return members
      .filter(
        (member) =>
          handles.has(member.user.name.toLowerCase()) ||
          handles.has(member.user.email.split("@")[0]?.toLowerCase() ?? ""),
      )
      .map((member) => member.userId);
  },
  highlightMentions: (body: string): string =>
    body.replace(/@([\w.-]+)/g, "<b>@$1</b>"),
};

/* ------------------------------------------------------------ @/lib/logger */

export const loggerModule = {
  createLogger: () => ({
    debug: () => undefined,
    info: () => undefined,
    warn: () => undefined,
    error: () => undefined,
  }),
};

/* --------------------------------------------------------------- @/lib/csv */

export const csvModule = {
  toCsv: (
    rows: readonly Readonly<
      Record<string, string | number | boolean | null>
    >[],
    columns: readonly string[],
  ): string =>
    [
      columns.join(","),
      ...rows.map((row) =>
        columns.map((column) => csvModule.escapeCsvValue(row[column] ?? null)).join(","),
      ),
    ].join("\n"),
  escapeCsvValue: (value: string | number | boolean | null): string => {
    const text = value === null ? "" : String(value);
    return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
  },
  csvResponseHeaders: (filename: string) => ({
    "content-type": "text/csv",
    "content-disposition": `attachment; filename="${filename}"`,
  }),
};

function simpleHash(value: string): string {
  let hash = 2_166_136_261;
  for (let i = 0; i < value.length; i += 1) {
    hash ^= value.charCodeAt(i);
    hash = Math.imul(hash, 16_777_619);
  }
  return Math.abs(hash).toString(36);
}
/**
 * Fixtures for the server suite: a throwaway SQLite file plus a helper that
 * builds one fully-populated tenant (org, four members, a project) through the
 * real repositories, so the rows under test are the rows production writes.
 *
 * Kept apart from `tests/helpers/*` — those belong to another owner.
 */
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { runMigrations } from "@/server/db/migrate";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as userRepo from "@/server/repositories/user-repository";
import type { PlanId } from "@/types/billing";
import type { OrgId, UserId } from "@/types/common";
import type { Actor, Role } from "@/types/member";
import type { Organization } from "@/types/organization";
import type { Project } from "@/types/project";

export interface Tenant {
  readonly org: Organization;
  readonly project: Project;
  readonly actors: Readonly<Record<Role, Actor>>;
  readonly userIds: Readonly<Record<Role, UserId>>;
}

const ROLES: readonly Role[] = ["owner", "admin", "member", "viewer"];

/**
 * Points the connection at a fresh database file and migrates it. Call from
 * `beforeAll`; the returned function removes the directory again.
 *
 * A file rather than `:memory:` because `runMigrations` and the app client
 * open separate connections, and only a file is shared between the two.
 */
export async function useTemporaryDatabase(): Promise<() => void> {
  const dir = mkdtempSync(join(tmpdir(), "taskflow-test-"));
  const path = join(dir, "taskflow.db");

  process.env.TASKFLOW_DB_PATH = path;
  await runMigrations(path);

  return () => {
    rmSync(dir, { recursive: true, force: true });
  };
}

/**
 * Creates one organization with a member in every role and a single project.
 * `plan` decides which quotas apply — the free plan's three seats is what the
 * invite-limit test leans on.
 */
export async function createTenant(
  slug: string,
  plan: PlanId = "growth",
): Promise<Tenant> {
  const owner = await userRepo.insertUser({
    email: `owner@${slug}.test`,
    name: `${slug} owner`,
    passwordHash: "seed",
  });

  const org = await orgRepo.insertOrg(
    { name: `${slug} inc`, slug, plan },
    owner.id,
  );

  await subscriptionRepo.insertSubscription(org.id, plan, "monthly");

  const userIds: Partial<Record<Role, UserId>> = {};
  const actors: Partial<Record<Role, Actor>> = {};

  for (const role of ROLES) {
    const user =
      role === "owner"
        ? owner
        : await userRepo.insertUser({
            email: `${role}@${slug}.test`,
            name: `${slug} ${role}`,
            passwordHash: "seed",
          });

    await memberRepo.insertMember(org.id, user.id, role, null);

    userIds[role] = user.id;
    actors[role] = { userId: user.id, orgId: org.id, role };
  }

  const project = await projectRepo.insertProject({
    orgId: org.id,
    name: `${slug} platform`,
    slug: "platform",
    key: "PLAT",
    description: null,
    visibility: "org",
    leadId: owner.id,
    color: "#6366f1",
    targetDate: null,
  });

  return {
    org,
    project,
    actors: actors as Readonly<Record<Role, Actor>>,
    userIds: userIds as Readonly<Record<Role, UserId>>,
  };
}

/** Minimal `CreateIssueInput` with the schema's defaults already applied. */
export function issueInput(
  orgId: OrgId,
  projectId: Project["id"],
  overrides: Partial<{
    title: string;
    assigneeId: UserId | null;
    dueAt: string | null;
  }> = {},
) {
  return {
    orgId,
    projectId,
    title: overrides.title ?? "Ship the thing",
    description: null,
    status: "backlog" as const,
    priority: "none" as const,
    assigneeId: (overrides.assigneeId ?? null) as UserId | null,
    parentId: null,
    estimate: null,
    dueAt: (overrides.dueAt ?? null) as never,
    labelIds: [],
  };
}
