/**
 * The subscription is the single authority on an org's plan: every quota,
 * feature gate, burst limit and displayed plan follows it as soon as it
 * changes — including for orgs whose records already disagree — and the trial
 * sweep only ever moves subscriptions that are still trialing.
 */
import { afterAll, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { eq } from "drizzle-orm";
import { consumeRateLimit, resetRateLimits } from "@/lib/rate-limit";
import { getDb, organizations, subscriptions } from "@/server/db";
import { runTrialExpiryJob } from "@/server/jobs/trial-expiry-job";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as activityService from "@/server/services/activity-service";
import * as billingService from "@/server/services/billing-service";
import * as invitationService from "@/server/services/invitation-service";
import * as projectService from "@/server/services/project-service";
import * as webhookService from "@/server/services/webhook-service";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";
import type { PlanId } from "@/types/billing";
import type { OrgId } from "@/types/common";
import type { Tenant } from "./_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

beforeEach(() => {
  resetRateLimits();
});

let slugCounter = 0;

async function tenantOn(plan: PlanId): Promise<Tenant> {
  slugCounter += 1;
  return createTenant(`authority${slugCounter}`, plan);
}

function projectInput(orgId: OrgId, n: number) {
  return {
    orgId,
    name: `Project ${n}`,
    slug: `project-${n}`,
    key: `P${n}`,
    description: null,
    visibility: "org" as const,
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  };
}

function subscriptionPlan(orgId: OrgId): PlanId | undefined {
  return getDb()
    .select()
    .from(subscriptions)
    .where(eq(subscriptions.orgId, orgId))
    .get()?.plan;
}

function orgColumnPlan(orgId: OrgId): PlanId | undefined {
  return getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get()?.plan;
}

const exportWindow = {
  since: "2020-01-01T00:00:00.000Z",
  until: "2030-01-01T00:00:00.000Z",
} as never;

describe("an upgrade", () => {
  it("lifts every plan-dependent guard at once", async () => {
    const tenant = await tenantOn("free");
    const orgId = tenant.org.id;
    const owner = tenant.actors.owner;

    await projectService.createProject(owner, projectInput(orgId, 2));
    await expect(
      projectService.createProject(owner, projectInput(orgId, 3)),
    ).rejects.toThrow(/projects/i);
    await expect(
      invitationService.inviteMember(owner, {
        orgId,
        email: "extra@example.test",
        role: "member",
      }),
    ).rejects.toThrow(/seats/i);
    await expect(
      activityService.exportActivity(owner, {
        orgId,
        format: "csv",
        ...exportWindow,
      }),
    ).rejects.toThrow(/not included/i);

    await billingService.changePlan(owner, { orgId, plan: "growth", interval: "monthly" });

    await expect(
      projectService.createProject(owner, projectInput(orgId, 3)),
    ).resolves.toBeDefined();
    await expect(
      invitationService.inviteMember(owner, {
        orgId,
        email: "extra@example.test",
        role: "member",
      }),
    ).resolves.toBeDefined();
    await expect(
      activityService.exportActivity(owner, {
        orgId,
        format: "csv",
        ...exportWindow,
      }),
    ).resolves.toEqual(expect.any(String));

    expect((await orgRepo.findOrgById(orgId))?.plan).toBe("growth");
    expect((await orgRepo.findOrgBySlug(tenant.org.slug))?.plan).toBe("growth");
    const listed = await orgRepo.listOrgsForUser(tenant.userIds.owner);
    expect(listed.find((org) => org.id === orgId)?.plan).toBe("growth");
  });

  it("does not touch another workspace", async () => {
    const upgraded = await tenantOn("free");
    const bystander = await tenantOn("free");

    await billingService.changePlan(upgraded.actors.owner, {
      orgId: upgraded.org.id,
      plan: "growth",
      interval: "monthly",
    });

    expect((await orgRepo.findOrgById(bystander.org.id))?.plan).toBe("free");
    expect(subscriptionPlan(bystander.org.id)).toBe("free");
  });
});

describe("a downgrade", () => {
  it("stops admins adding webhook endpoints", async () => {
    const tenant = await tenantOn("growth");
    const orgId = tenant.org.id;
    const owner = tenant.actors.owner;

    await webhookService.createWebhook(owner, {
      orgId,
      url: "https://hooks.example.test/one",
      eventTypes: ["issue.created"],
    });

    await billingService.changePlan(owner, { orgId, plan: "starter", interval: "monthly" });

    await expect(
      webhookService.createWebhook(owner, {
        orgId,
        url: "https://hooks.example.test/two",
        eventTypes: ["issue.created"],
      }),
    ).rejects.toThrow(/not included/i);
  });

  it("changes nothing when it is refused", async () => {
    const tenant = await tenantOn("growth");
    const orgId = tenant.org.id;
    await usageRepo.recomputeUsage(orgId);

    await expect(
      billingService.changePlan(tenant.actors.owner, {
        orgId,
        plan: "free",
        interval: "monthly",
      }),
    ).rejects.toThrow(/Cannot move/);

    expect(subscriptionPlan(orgId)).toBe("growth");
    expect(orgColumnPlan(orgId)).toBe("growth");
    expect((await orgRepo.findOrgById(orgId))?.plan).toBe("growth");
  });
});

describe("records that already disagree", () => {
  it("follows a subscription that is behind the org column", async () => {
    const tenant = await tenantOn("growth");
    const orgId = tenant.org.id;
    getDb()
      .update(subscriptions)
      .set({ plan: "free" })
      .where(eq(subscriptions.orgId, orgId))
      .run();

    expect(orgColumnPlan(orgId)).toBe("growth");
    expect((await orgRepo.findOrgById(orgId))?.plan).toBe("free");
    await expect(
      projectService.createProject(tenant.actors.owner, projectInput(orgId, 2)),
    ).resolves.toBeDefined();
    await expect(
      projectService.createProject(tenant.actors.owner, projectInput(orgId, 3)),
    ).rejects.toThrow(/projects/i);
    await expect(
      billingService.checkLimit(orgId, "projects"),
    ).resolves.toMatchObject({ plan: "free" });
  });

  it("follows a subscription that is ahead of the org column", async () => {
    const tenant = await tenantOn("free");
    const orgId = tenant.org.id;
    getDb()
      .update(subscriptions)
      .set({ plan: "growth" })
      .where(eq(subscriptions.orgId, orgId))
      .run();

    expect(orgColumnPlan(orgId)).toBe("free");
    expect((await orgRepo.findOrgById(orgId))?.plan).toBe("growth");
    await expect(
      invitationService.inviteMember(tenant.actors.owner, {
        orgId,
        email: "late@example.test",
        role: "member",
      }),
    ).resolves.toBeDefined();
  });

  it("uses the org's own plan when there is no subscription", async () => {
    const tenant = await tenantOn("growth");
    const orgId = tenant.org.id;
    getDb().delete(subscriptions).where(eq(subscriptions.orgId, orgId)).run();

    expect((await orgRepo.findOrgById(orgId))?.plan).toBe("growth");
    await expect(
      billingService.checkLimit(orgId, "seats"),
    ).resolves.toMatchObject({ plan: "growth", limit: 50 });
  });
});

describe("burst limits", () => {
  it("grow when the plan is upgraded", async () => {
    const tenant = await tenantOn("free");
    const orgId = tenant.org.id;

    for (let i = 0; i < 60; i += 1) {
      expect((await consumeRateLimit(orgId, "comment:create")).allowed).toBe(true);
    }
    expect((await consumeRateLimit(orgId, "comment:create")).allowed).toBe(false);

    await billingService.changePlan(tenant.actors.owner, {
      orgId,
      plan: "growth",
      interval: "monthly",
    });

    for (let i = 0; i < 200; i += 1) {
      expect((await consumeRateLimit(orgId, "comment:create")).allowed).toBe(true);
    }
  });

  it("shrink when the plan is downgraded", async () => {
    const tenant = await tenantOn("growth");
    const orgId = tenant.org.id;

    expect((await consumeRateLimit(orgId, "comment:create")).allowed).toBe(true);
    await billingService.changePlan(tenant.actors.owner, {
      orgId,
      plan: "starter",
      interval: "monthly",
    });

    let allowed = 0;
    while ((await consumeRateLimit(orgId, "comment:create")).allowed) {
      allowed += 1;
      if (allowed > 10_000) break;
    }
    expect(allowed).toBeLessThanOrEqual(600);
  });

  it("belong to one workspace only", async () => {
    const busy = await tenantOn("free");
    const other = await tenantOn("free");

    for (let i = 0; i < 60; i += 1) await consumeRateLimit(busy.org.id, "comment:create");
    await billingService.changePlan(busy.actors.owner, {
      orgId: busy.org.id,
      plan: "growth",
      interval: "monthly",
    });

    for (let i = 0; i < 60; i += 1) {
      expect((await consumeRateLimit(other.org.id, "comment:create")).allowed).toBe(true);
    }
    expect((await consumeRateLimit(other.org.id, "comment:create")).allowed).toBe(false);
  });
});

describe("the trial sweep", () => {
  const AFTER_TRIAL = () => new Date(Date.now() + 30 * 24 * 60 * 60 * 1000);

  it("moves a trial to free and the workspace follows", async () => {
    const tenant = await tenantOn("growth");
    const orgId = tenant.org.id;
    await usageRepo.recomputeUsage(orgId);

    // The fixture leaves four members, which the free plan cannot hold.
    getDb().delete(subscriptions).where(eq(subscriptions.orgId, orgId)).run();
    await subscriptionRepo.insertSubscription(orgId, "growth", "monthly");
    getDb()
      .update(usageRepoSeatsTable())
      .set({ seatsUsed: 1, projectsUsed: 1 })
      .where(eq(usageRepoSeatsTable().orgId, orgId))
      .run();

    const first = await runTrialExpiryJob(AFTER_TRIAL());
    expect(first.processed).toBeGreaterThanOrEqual(1);

    expect(subscriptionPlan(orgId)).toBe("free");
    expect((await orgRepo.findOrgById(orgId))?.plan).toBe("free");
    await projectService.createProject(tenant.actors.owner, projectInput(orgId, 2));
    await expect(
      projectService.createProject(tenant.actors.owner, projectInput(orgId, 3)),
    ).rejects.toThrow(/projects/i);

    const before = await subscriptionRepo.findSubscription(orgId);
    const second = await runTrialExpiryJob(AFTER_TRIAL());
    expect(second.processed).toBe(0);
    expect(await subscriptionRepo.findSubscription(orgId)).toEqual(before);
  });

  it("leaves a workspace that chose a paid plan during its trial alone", async () => {
    const tenant = await tenantOn("starter");
    const orgId = tenant.org.id;
    await billingService.changePlan(tenant.actors.owner, {
      orgId,
      plan: "growth",
      interval: "monthly",
    });

    await runTrialExpiryJob(AFTER_TRIAL());

    expect(subscriptionPlan(orgId)).toBe("growth");
    expect((await orgRepo.findOrgById(orgId))?.plan).toBe("growth");
  });

  it("leaves a trial that outgrew the free limits on its plan", async () => {
    const tenant = await tenantOn("growth");
    const orgId = tenant.org.id;
    await usageRepo.recomputeUsage(orgId);

    await runTrialExpiryJob(AFTER_TRIAL());

    expect(subscriptionPlan(orgId)).toBe("growth");
    expect((await orgRepo.findOrgById(orgId))?.plan).toBe("growth");
  });
});

function usageRepoSeatsTable() {
  return organizationUsageTable;
}

