  const AFTER_TRIAL = () => new Date(Date.now() + 30 * 24 * 60 * 60 * 1000);

  it("moves a trial to free and the workspace follows", async () => {
    const tenant = await tenantOn("growth");
    const orgId = tenant.org.id;
    await usageRepo.recomputeUsage(orgId);

    // The fixture leaves four members, which the free plan cannot hold.
    getDb().delete(subscriptions).where(eq(subscriptions.orgId, orgId)).run();
    await subscriptionRepo.insertSubscription(orgId, "growth", "monthly");
    getDb()
      .update(usageRepoSeatsTable())
      .set({ seatsUsed: 1, projectsUsed: 1 })
      .where(eq(usageRepoSeatsTable().orgId, orgId))
      .run();

    const first = await runTrialExpiryJob(AFTER_TRIAL());
    expect(first.processed).toBeGreaterThanOrEqual(1);

    expect(subscriptionPlan(orgId)).toBe("free");
    expect((await orgRepo.findOrgById(orgId))?.plan).toBe("free");
    await projectService.createProject(tenant.actors.owner, projectInput(orgId, 2));
    await expect(
      projectService.createProject(tenant.actors.owner, projectInput(orgId, 3)),
    ).rejects.toThrow(/projects/i);

    const before = await subscriptionRepo.findSubscription(orgId);
    const second = await runTrialExpiryJob(AFTER_TRIAL());
    expect(second.processed).toBe(0);
    expect(await subscriptionRepo.findSubscription(orgId)).toEqual(before);
  });

  it("leaves a workspace that chose a paid plan during its trial alone", async () => {
    const tenant = await tenantOn("starter");
    const orgId = tenant.org.id;
    await billingService.changePlan(tenant.actors.owner, {
      orgId,
      plan: "growth",
      interval: "monthly",
    });

    await runTrialExpiryJob(AFTER_TRIAL());

    expect(subscriptionPlan(orgId)).toBe("growth");
    expect((await orgRepo.findOrgById(orgId))?.plan).toBe("growth");
  });

  it("leaves a trial that outgrew the free limits on its plan", async () => {
    const tenant = await tenantOn("growth");
    const orgId = tenant.org.id;
    await usageRepo.recomputeUsage(orgId);

    await runTrialExpiryJob(AFTER_TRIAL());

    expect(subscriptionPlan(orgId)).toBe("growth");
    expect((await orgRepo.findOrgById(orgId))?.plan).toBe("growth");
  });
});

function usageRepoSeatsTable() {
  return organizationUsageTable;
}

